#ifdef GL_ES
precision mediump float;
#endif


#define PI 3.1415926535897932384626433832795
#define MAX_STEPS 100
#define MAX_DIST 100.0
#define SURF_DIST .1
#define SUN vec3(-5.0, 10.0, -5.0)
#define ZOOM 1.0
#define DISTANCE 5.0
#define EPSILON .1

mat2 Rot(float a)
{
  float s = sin(a);
  float c = cos(a);
  return mat2(c, -s, s, c);
}
vec3 R(vec2 uv, vec3 p, vec3 l, float z) {
    vec3 f = normalize(l-p),
        r = normalize(cross(vec3(0,1,0), f)),
        u = cross(f,r),
        c = p+f*z,
        i = c + uv.x*r + uv.y*u,
        d = normalize(i-p);
    return d;
}
float Sphere(vec3 p, vec3 o, float radius)
{
  return length(p - o) - radius ;
}
float Plane(vec3 p, float h)
{
  return p.y - h;
}
float Box(vec3 p, vec3 b)
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}
float Cylinder( vec3 p, vec3 c )
{
  return length(p.xz-c.xy)-c.z;
}
float Capsule( vec3 p, vec3 a, vec3 b, float r )
{
  vec3 pa = p - a, ba = b - a;
  float h = dot(pa,ba)/dot(ba,ba);
  return length( pa - ba*h ) - r;
}
vec3 RandomVector(float i) {
    return normalize(vec3(sin(329.34+131.8*sin(722.1*i+8.23)),
                            sin(494.34+2871.1*sin(431.1*i+415.39)),
                            sin(757.34+9539.1*sin(161.1*i+201.39)))
                );
}
float SmoothMin(float a, float b)
{
    float k = 3.0;
    float h = pow( max( (k-abs(a-b))/k , 0.0), 3.0) * k / 6.0;
    return min(a,b) - h;
}
float GetDist(vec3 p)
{
  float displacement = sin(5.0 * p.x) * sin(5.0 * p.y) * sin(5.0 * p.z) * 0.25;
  p += displacement;

  float dSphere = Sphere(p, vec3(0.0, 0.0, 0.0), 2.0 + (sin(iTime*2.0) * 0.5));

  float d = dSphere;

  for(float i = 0.0; i < 3.0; i += 0.1)
  {
      vec3 pos = RandomVector(i) + vec3(sin(iTime+i*4.0));
      float off = sin(iTime*5.0 + floor(i*4.0)) * 0.5 + 1.5;
      pos *= off*2.0;
      float dSmallSphere = Sphere(p, pos, 0.1);

      d = SmoothMin(d, dSmallSphere);
  }

  return d;
}
vec2 RayMarch(vec3 ro, vec3 rd)
{

  float dO = 0.0;
  float d;
  float minD = 10000.0;
  vec3 p;
  for(int i = 0; i < MAX_STEPS; i++)
  {
    p = ro + rd * dO;
    d = GetDist(p);
    if(d < minD)
      minD = d;
    dO += d;
    if(abs(dO) < SURF_DIST || dO > MAX_DIST)
      break;
  }
  return vec2(dO, minD);

}
vec3 GetNormal(vec3 p)
{
  vec2 e = vec2(.01, .0);
  float d = GetDist(p);
  vec3 n = vec3(
    d - GetDist(p - vec3(e.xyy)),
    d - GetDist(p - vec3(e.yxy)),
    d - GetDist(p - vec3(e.yyx))
  );


  return normalize(n);
}

float GetShadow(vec3 p, vec3 s)
{
  float d = RayMarch(p, s).x;
  float ds = length(SUN - p);

  return step(EPSILON, d - ds);
}
float GetLight(vec3 p)
{
  if ( length(p) > MAX_DIST / 2.0 )
    return 0.0; 

  vec3 s = normalize(SUN - p);
  vec3 n = GetNormal(p);


  float l = dot(n, s);
  l = clamp(l, 0.0, 1.0);

  p += n * SURF_DIST * 3.0;
  float sh = 1.0;GetShadow(p, s) + .1;


  return l * sh;
}
void mainImage( out vec4 fragColor, in vec2 fragCoord ) {

  vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;


  vec3 c = vec3(0.0);

  vec3 ro = vec3(0, 4, -5);
  ro.yz *= Rot(sin(iTime) * .1);
  ro.xz *= Rot(sin(iTime / 2.0)*PI/ 2.0);

  vec3 rd = R(uv, ro, vec3(0,0,0), .7);


  vec2 d = RayMarch(ro, rd);
  vec3 p = ro + rd * d.x;



  c = vec3(abs(GetLight(p) + 0.5)) / 1.5;// + GetNormal(p)) * 0.5;

  //c = GetNormal(p) *  pow ( ((GetLight(p) + .2) / 1.2), 2.0);
    c *= uv.xyx + vec3(0.5);
  fragColor = vec4(c, 1.0);

  if(d.x > MAX_DIST)
    fragColor = vec4(0.1);
}
